('00000009-0009-4009-8009-000000000009', 1, 'teach', 'Sergio, "Onde fica o supermercado, por favor?" em inglês é "Where is the supermarket, please?". Listen: Where is the supermarket, please?. Agora repita.', 'Where is the supermarket, please?', 0.06),
('00000009-0009-4009-8009-000000000009', 2, 'repeat', 'Muito bem! Diga de novo, com ritmo natural.', 'Where is the supermarket, please?', NULL),
('00000009-0009-4009-8009-000000000009', 3, 'question', 'Como se diz "Vá em frente e vire à esquerda." em inglês?', 'Go straight and turn left.', NULL),
('00000009-0009-4009-8009-000000000009', 4, 'praise', 'Excelente! Você está pronto para o próximo passo.', NULL, 0.05),
