-- ---------------------------------------------------------------------------
-- Hupy 60-planet curriculum (generated by scripts/generate-curriculum.py).
--
-- Expands the course from 8 planets to the full 60-planet journey (6 phases,
-- A1 -> C1), converts every planet to the standard 10-block path, seeds key
-- sentences and scripted lesson steps for the new planets — for all six
-- base->target courses. Regenerate with:  python3 scripts/generate-curriculum.py
-- ---------------------------------------------------------------------------

-- 1. Planet metadata: level (A1..C1) + communication goal
ALTER TABLE planets ADD COLUMN level VARCHAR(8) NOT NULL DEFAULT 'A1';
ALTER TABLE planets ADD COLUMN goal TEXT NOT NULL DEFAULT '';

UPDATE planets SET level = CASE
    WHEN number <= 10 THEN 'A1'
    WHEN number <= 20 THEN 'A2'
    WHEN number <= 30 THEN 'B1'
    WHEN number <= 40 THEN 'B2'
    WHEN number <= 50 THEN 'B2+'
    ELSE 'C1'
END;

UPDATE planets SET goal = 'Apresente-se e faça seus primeiros contatos em inglês' WHERE number = 1;
UPDATE planets SET goal = 'Fale sobre sua rotina e ações do dia a dia' WHERE number = 2;
UPDATE planets SET goal = 'Peça ajuda, combine horários e resolva problemas' WHERE number = 3;
UPDATE planets SET goal = 'Peça comida, cozinhe e faça compras' WHERE number = 4;
UPDATE planets SET goal = 'Pergunte direções e viaje com confiança' WHERE number = 5;
UPDATE planets SET goal = 'Fale sobre saúde, corpo e emoções' WHERE number = 6;
UPDATE planets SET goal = 'Conduza reuniões, e-mails e ligações profissionais' WHERE number = 7;
UPDATE planets SET goal = 'Dê opiniões, conte histórias e use expressões naturais' WHERE number = 8;

-- 2. New planets (9-60) for all six courses

-- 3. Blocks: convert every planet to the standard 10-block path
-- The old rows are removed first so the tightened kind check cannot
-- be violated by the legacy 4-kind path.
DELETE FROM planet_lessons;

DO $$ BEGIN
    IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'planet_lessons_kind_check') THEN
        ALTER TABLE planet_lessons DROP CONSTRAINT planet_lessons_kind_check;
    END IF;
END $$;
ALTER TABLE planet_lessons ADD CONSTRAINT planet_lessons_kind_check CHECK (kind IN ('context', 'vocabulary', 'phrases', 'structure', 'listening', 'pronunciation', 'recall', 'variations', 'conversation', 'mission'));

SELECT p.id, b.position, b.kind, b.title, b.description
FROM planets p
CROSS JOIN (VALUES
    (1, 'context', 'Context & Diagnosis', 'Meet the theme in a real situation and show what you already know'),
    (2, 'vocabulary', 'Essential Vocabulary', 'Learn only the words and expressions you really need'),
    (3, 'phrases', 'Fundamental Phrases', 'Master the key sentences of this planet'),
    (4, 'structure', 'Sentence Building', 'Build sentences: subject, verb, complement, time and place'),
    (5, 'listening', 'Listening Comprehension', 'Understand phrases and dialogues spoken naturally'),
    (6, 'pronunciation', 'Pronunciation & Shadowing', 'Listen and repeat — clarity, rhythm and intonation'),
    (7, 'recall', 'Active Recall', 'Produce the language from memory, without copying'),
    (8, 'variations', 'Variations & Transformations', 'Turn statements into questions, past into future, and more'),
    (9, 'conversation', 'Practical Conversation', 'Have a real conversation using what you learned'),
    (10, 'mission', 'Planet Mission', 'Use everything together and conquer the planet')
) AS b(position, kind, title, description)
ORDER BY p.number, b.position;

